package io.knowledgebrain.integration;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.http.HttpMethod;
@Configuration class SecurityConfiguration {@Bean SecurityFilterChain securityFilterChain(HttpSecurity http,@Value("${brain.integration.api.enabled:false}")boolean api,@Value("${brain.integration.activity-export.enabled:false}")boolean export)throws Exception{http.sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).requestCache(c->c.disable());if(api)http.csrf(c->c.ignoringRequestMatchers("/api/spaces/*/github/repositories","/api/spaces/*/github/repositories/*","/api/spaces/*/github/repositories/*/sync","/api/spaces/*/github/repositories/*/work-items/ISSUE/sync","/api/spaces/*/github/repositories/*/work-items/PULL_REQUEST/sync"));return http.authorizeHttpRequests(a->{a.requestMatchers("/actuator/health","/actuator/health/liveness","/actuator/health/readiness").permitAll();if(export)a.requestMatchers(HttpMethod.GET,"/internal/integration/activity-events").permitAll();if(api){String root="/api/spaces/*/github/repositories";a.requestMatchers(HttpMethod.GET,root,root+"/*",root+"/*/commits",root+"/*/commits/*",root+"/*/revisions",root+"/*/syncs",root+"/*/commits/*/reference",root+"/*/work-items",root+"/*/work-items/*",root+"/*/work-items/*/revisions",root+"/*/work-items/ISSUE/sync-state",root+"/*/work-items/PULL_REQUEST/sync-state",root+"/*/work-items/ISSUE/syncs",root+"/*/work-items/PULL_REQUEST/syncs").permitAll();a.requestMatchers(HttpMethod.POST,root,root+"/*/sync",root+"/*/work-items/ISSUE/sync",root+"/*/work-items/PULL_REQUEST/sync").permitAll();a.requestMatchers(HttpMethod.DELETE,root+"/*").permitAll();}a.anyRequest().denyAll();}).build();}}
